export const FITS_STD_LIB_WASM_BASE64 =
  "";

let cachedWasmBytes: Uint8Array | undefined;

/**
 * Decodes the pre-bundled `@modelscript/fits-std-lib` `runtime.wasm` binary in Node.js, Browsers, or Web Workers.
 */
export function getFitsStdLibWasmBytes(): Uint8Array {
  if (!cachedWasmBytes) {
    cachedWasmBytes = decodeBase64Wasm(FITS_STD_LIB_WASM_BASE64);
  }
  return cachedWasmBytes;
}
